/* Client PDF viewers are full pages, Figma 200:7741 and 200:7872. */
function clientDocumentPaper(type){
 const q=state.quote,r=state.request,t=totals(q),count=q.rooms.reduce((s,x)=>s+x.qty,0);
 const facts=type==='contract'?[['CLIENT',r.organization+' · '+name()],['VENUE','Cedar Valley Retreat & Conference Center'],['EVENT',r.group],['DATES',dates()]]:[['GROUP',r.group],['ORGANIZER',name()],['DATES',dates()+' · '+nights()+' nights'],['ROOMS',requestRoomSummary(r)]];
 const docTable=(heads,rows)=>'<table><thead><tr>'+heads.map(h=>'<th>'+h+'</th>').join('')+'</tr></thead><tbody>'+rows.map(row=>'<tr>'+row.map(c=>'<td>'+c+'</td>').join('')+'</tr>').join('')+'</tbody></table>';
 const clauses=contractClauses();
 const body=type==='contract'?clauses.map(([title,text])=>'<section class="client-doc-clause"><h3>'+title+'</h3><p>'+esc(text)+'</p></section>').join(''):'<h3>AGENDA</h3>'+docTable(['Session','Day','Time','Location','Guests'],scheduleRows().map(row=>[esc(row[2]),esc(row[0]),row[1],esc(row[3]),r.guests]))+'<h3>ROOM SETUP</h3>'+docTable(['Room type','Qty','Rate','Total'],q.rooms.filter(x=>x.qty>0).map(x=>[esc(x.type)+' ('+nights()+' nights)',x.qty,money(x.rate),money(x.qty*x.rate*nights())]))+'<h3>ADD-ONS</h3>'+docTable(['Add-on','Qty','Rate','Total'],quoteRows(q).slice(q.rooms.filter(x=>x.qty>0).length).map(row=>[row[0],row[1],row[3],row[4]]))+'<div class="client-doc-totals">'+line('Rooms',money(t.rooms))+line('Add-ons',money(t.space+t.addons))+(t.discount?line('Discount','−'+money(t.discount)):'')+line('Taxes ('+(q.tax?'10':'0')+'%)',money(t.tax))+(t.storedValueAmount?line('Stored Value','−'+money(t.storedValueAmount)):'')+line('Total',money(t.total),'doc-total')+line(q.paid?'Deposit paid (50%)':'Deposit due on signing (50%)',money(q.payment?.amount||t.deposit))+line('Balance due '+dueDate(),money(t.total-(q.payment?.amount||t.deposit)))+'</div>';
 return '<article class="client-doc-paper '+type+'"><div class="client-doc-brand"><div><b>CEDAR VALLEY</b><small>Retreat & Conference Center</small></div><div><small>'+ (type==='beo'?'BANQUET EVENT ORDER':'GROUP BOOKING CONTRACT')+'</small><strong>GBR-008</strong></div></div><div class="client-doc-facts">'+facts.map(([k,v])=>'<div><small>'+k+'</small><b>'+esc(v)+'</b></div>').join('')+'</div>'+body+(q.beoNotes&&type==='beo'?'<h3>EVENT NOTES</h3><p>'+esc(q.beoNotes)+'</p>':'')+'<div class="client-doc-signatures">'+[['Client signature',name()+' · '+r.organization,q.signature],['Venue signature','Cedar Valley Retreat & Conference Center',q.venueConfirmed?q.venueSignature||{name:'Jordan Reyes'}:null]].map(([title,who,sig])=>'<div><p>'+esc(sig?.name||'')+'</p><b>'+title+'</b><small>'+esc(who)+'</small><small>'+(sig?'Signed electronically · Sep 22, 2026':'Date: ____ / ____ / ________')+'</small></div>').join('')+'</div></article>';
}
function clientDocumentPage(){const type=state.ui.clientDocument||'beo',q=state.quote;return '<div class="client-doc-viewer"><header class="client-viewer-bar"><div>'+button('← Back to overview','client-doc-back')+'<i></i><b>'+(type==='beo'?'BEO':'Contract')+'_GBR-008.pdf</b><small>'+(type==='beo'?'Version 2 · Sep 12, 2026':q.signature?'Signed electronically':'Needs your signature')+'</small></div><div><small>Page 1 of 1</small>'+button('Download','download-'+type)+button('Print','client-doc-print')+(type==='contract'&&!q.signature?button('Continue to sign','client-doc-sign','primary'):'')+'</div></header><main class="client-doc-stage">'+clientDocumentPaper(type)+'</main></div>';}
const clientDocRender=render,clientDocHandle=handle;
render=function(){if(state.ui.app==='guest'&&state.ui.guest==='document-viewer'){$('#demo').innerHTML=demoBar();$('#app').innerHTML=clientDocumentPage();renderOverlay();return;}clientDocRender();};
handle=function(a,el){if(state.ui.app==='guest'&&['doc-contract','doc-beo'].includes(a)&&state.quote){state.ui.clientDocument=a.slice(4);modal=null;return navigate('guest','document-viewer');}if(a==='client-doc-back'){modal=null;return state.quote.status==='Sent'&&!state.quote.signature?navigate('guest','review'):openOrganizerPortal();}if(a==='client-doc-sign'){modal=null;state.ui.portalRole='organizer';state.ui.portalPage='documents';return navigate('guest','sign');}if(a==='client-doc-print')return window.print();return clientDocHandle(a,el);};
render();
